import base64, cv2, pytesseract

def preprocess(path: str) -> bytes:
    img = cv2.imread(path)
    img = deskew(crop_to_document(img))
    h, w = img.shape[:2]
    scale = 1568 / max(h, w)                       # stay within the model's limit
    img = cv2.resize(img, (int(w * scale), int(h * scale)))
    return cv2.imencode(".jpg", img)[1].tobytes()

def read(path: str) -> dict:
    jpg = preprocess(path)
    fields = vision_extract(                         # structured output (Prompting & Structured Outputs)
        image_b64=base64.b64encode(jpg).decode(), schema=ClaimDocument)
    ocr_text = pytesseract.image_to_string(jpg_to_array(jpg), lang="hin+eng+mar")
    disagreements = [f for f in ("total_amount", "bill_date", "patient_name")
                     if not appears_in(fields[f], ocr_text)]
    if disagreements:
        return {"status": "review", "fields": fields, "check": disagreements}
    return {"status": "accepted", "fields": fields}

from urllib.parse import urlparse

ALLOWED = {"ops.bank.internal", "portal.vendor.example", "www.npci.org.in"}
IRREVERSIBLE = ("pay", "confirm", "submit", "reverse", "delete", "approve")

class Policy:
    def __init__(self, session, approver, max_steps=60):
        self.s, self.approver, self.steps = session, approver, 0
        self.max_steps = max_steps

    def check(self, action: dict) -> dict:
        self.steps += 1
        if self.steps > self.max_steps:
            return {"deny": "step limit reached"}
        if urlparse(self.s.current_url).hostname not in ALLOWED:
            return {"deny": "domain not on the allowlist"}
        if action["name"] == "left_click":
            label = self.s.element_label_at(action["input"]["coordinate"]).lower()
            if any(word in label for word in IRREVERSIBLE):
                if not self.approver.confirm(label, self.s.screenshot()):
                    return {"deny": "person declined"}
        if action["name"] == "type" and self.s.focused_is_password():
            self.s.fill_from_vault()               # the model never sees the secret
            return {"handled": "credential filled from vault"}
        self.s.record(action)
        return {"allow": True}

import re
from collections import defaultdict
import jiwer

NUM = {"ek": 1, "do": 2, "teen": 3, "chaar": 4, "char": 4, "paanch": 5, "panch": 5,
       "chhe": 6, "saat": 7, "aath": 8, "nau": 9, "das": 10, "bees": 20,
       "pachees": 25, "tees": 30, "chaalees": 40, "pachaas": 50, "sattar": 70,
       "dedh": 1.5, "dhai": 2.5}
SCALE = {"sau": 100, "hazaar": 1_000, "hazar": 1_000, "lakh": 1_00_000, "crore": 1_00_00_000}
ADJUST = {"saadhe": 0.5, "sava": 0.25, "paune": -0.25}   # 3½, 2¼, 3¾ ...

def words_to_rupees(text):
    """'saadhe teen hazaar' -> 3500, 'dhai lakh' -> 250000, '12,500' -> 12500."""
    total, cur, adj, seen = 0, 0, 0, False
    for w in re.findall(r"[a-z]+|\d[\d,]*", text.lower()):
        if w[0].isdigit():
            cur += int(w.replace(",", "")); seen = True
        elif w in ADJUST:
            adj = ADJUST[w]
        elif w in NUM:
            cur += NUM[w]; seen = True
        elif w in SCALE and seen:
            total += ((cur or 1) + adj) * SCALE[w]
            cur, adj = 0, 0
    return round(total + cur) if seen else None

def inr(n):
    """Indian digit grouping: 250000 -> '2,50,000'."""
    s = str(n)
    if len(s) <= 3:
        return s
    head, tail = s[:-3], s[-3:]
    head = re.sub(r"(\d)(?=(\d\d)+$)", r"\1,", head)
    return f"{head},{tail}"

def score_by_language(rows):
    """rows: (language, reference, hypothesis) from your own transcribed calls."""
    by_lang = defaultdict(lambda: ([], []))
    for lang, ref, hyp in rows:
        by_lang[lang][0].append(ref)
        by_lang[lang][1].append(hyp)
    return {lang: (jiwer.wer(refs, hyps), jiwer.cer(refs, hyps))
            for lang, (refs, hyps) in by_lang.items()}

if __name__ == "__main__":
    for said in ["saadhe teen hazaar", "dhai lakh", "paune chaar hazaar",
                 "teen hazaar paanch sau", "sava do lakh", "premium 12,500 hai"]:
        print(f"{said!r:28} -> ₹{inr(words_to_rupees(said))}")
    rows = [("hi", "mera premium kab due hai", "mera premium kab due hai"),
            ("hi", "policy lapse ho gayi kya", "policy laps ho gayi kya"),
            ("ta", "en policy number sollunga", "en policy nambar sollunga")]
    for lang, (wer, cer) in score_by_language(rows).items():
        print(lang, f"WER {wer:.0%}  CER {cer:.0%}")

